module min_time_path (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire setup_mode,\n    input wire volcano_valid,\n    input wire [3:0] volcano_x,\n    input wire [3:0] volcano_y,\n    input wire [3:0] n,\n    output reg done,\n    output reg [7:0] result\n);\n\n    // State declarations\n    localparam [1:0] IDLE   = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n    reg [1:0] state_reg, next_state;\n\n    // Grid indices and DP storage\n    reg [3:0] i_reg, j_reg;\n    reg [15:0] prev_row_reg;\n    reg [15:0] curr_row_reg;\n    reg [15:0] blocked_rows [0:15];  // 16x16 grid storage\n\n    // Combinational path logic\n    wire bit_val;\n    assign bit_val = (blocked_rows[i_reg][j_reg] == 1'b1) ? 1'b0 :\n                     (i_reg == 4'd0 && j_reg == 4'd0) ? 1'b1 :\n                     ((i_reg > 4'd0 && prev_row_reg[j_reg]) ||\n                      (j_reg > 4'd0 && curr_row_reg[j_reg-4'd1]));\n\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state_reg <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            i_reg <= 4'd0;\n            j_reg <= 4'd0;\n            prev_row_reg <= 16'd0;\n            curr_row_reg <= 16'd0;\n            // Clear blocked grid\n            for (i = 0; i < 16; i = i + 1) begin\n                blocked_rows[i] <= 16'd0;\n            end\n        end else begin\n            state_reg <= next_state;\n            case (state_reg)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize computation\n                        i_reg <= 4'd0;\n                        j_reg <= 4'd0;\n                        prev_row_reg <= 16'd0;\n                        curr_row_reg <= 16'd0;\n                        next_state <= COMPUTE;\n                    end else if (setup_mode && volcano_valid) begin\n                        // Record volcano location\n                        blocked_rows[volcano_x][volcano_y] <= 1'b1;\n                        next_state <= IDLE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    // Update current cell\n                    curr_row_reg[j_reg] <= bit_val;\n\n                    // Next cell logic\n                    if (j_reg == (n - 4'd1)) begin\n                        j_reg <= 4'd0;\n                        if (i_reg == (n - 4'd1)) begin\n                            // Reached bottom-right cell\n                            next_state <= DONE_STATE;\n                        end else begin\n                            i_reg <= i_reg + 4'd1;\n                            prev_row_reg <= curr_row_reg;\n                            curr_row_reg <= 16'd0;\n                            next_state <= COMPUTE;\n                        end\n                    end else begin\n                        j_reg <= j_reg + 4'd1;\n                        next_state <= COMPUTE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    // Output result and done signal\n                    done <= 1'b1;\n                    result <= bit_val ? {3'd0, (n - 4'd1)} << 1 : 8'hFF;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule